application.css:
* { box-sizing: border-box; }

:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef2f7;
}

body { margin: 0; min-width:  min(100%, 320px); }
.page-shell { width: min(100% - 2rem, 780px); margin: 0 auto; padding: 2.5rem 0 3rem; }
.quiz-header { margin-bottom: 1.75rem; }
.eyebrow { margin: 0 0 .35rem; color: #3159a6; font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .7rem; font-size: clamp(1.8rem, 5vw, 2.7rem); }
.quiz-header p:last-child { max-width: 58ch; margin: 0; color: #48566d; }
.questions { display: grid; gap: 1rem; }
.question-card { min-inline-size: 0; margin: 0; padding: 1.25rem; border: 1px solid #cbd4e2; border-radius: .7rem; background: #fff; }
legend { max-width: 100%; padding: 0; font-weight: 700; font-size: 1.05rem; }
.question-number { display: block; margin-bottom: .3rem; color: #3159a6; font-size: .8rem; text-transform: uppercase; letter-spacing: .06em; }
.options { display: grid; gap: .65rem; margin-top: 1rem; }
.option { display: flex; align-items: center; gap: .7rem; padding: .75rem .85rem; border: 1px solid #b8c4d5; border-radius: .45rem; cursor: pointer; }
.option:hover { background: #f3f6fb; }
.option:has(input:checked) { border-color: #3159a6; background: #eaf0fc; }
.option input { width: 1.1rem; height: 1.1rem; accent-color: #3159a6; }
.question-error { display: none; margin: .65rem 0 0; color: #a32929; font-size: .9rem; }
.question-card.invalid { border-color: #b32929; }
.question-card.invalid .question-error { display: block; }
.actions { display: flex; align-items: center; flex-wrap: wrap; gap: 1rem; margin-top: 1.4rem; }
button { border: 0; border-radius: .45rem; padding: .8rem 1.2rem; color: #fff; background: #244b91; font: inherit; font-weight: 700; cursor: pointer; }
button:hover { background: #183970; }
button:focus-visible, input:focus-visible, .option:has(input:focus-visible) { outline: 3px solid #f0a52b; outline-offset: 2px; }
.form-message { margin: 0; color: #a32929; font-weight: 600; }
.result { margin-top: 1.5rem; padding: 1.25rem; border-radius: .7rem; background: #172033; color: #fff; }
.result h2 { margin: 0 0 .35rem; font-size: 1rem; }
.score { margin: 0; font-size: 1.5rem; font-weight: 700; }
@media (max-width: 480px) { .page-shell { width: min(100% - 1.25rem, 780px); padding-top: 1.5rem; } .actions { align-items: stretch; flex-direction: column; } button { width: 100%; } }

application.javascript:
const form = document.querySelector('#quiz-form');
const questionCards = [...document.querySelectorAll('[data-testid="quiz-question"]')];
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const messageElement = document.querySelector('#form-message');
const correctAnswers = ['paris', '4', 'blue'];

function getSelectedValue(card) {
  const selected = card.querySelector('input[type="radio"]:checked');
  return selected ? selected.value : null;
}

function clearQuestionError(card) {
  card.classList.remove('invalid');
}

function validateAnswers() {
  let isComplete = true;
  questionCards.forEach((card) => {
    const selectedValue = getSelectedValue(card);
    if (selectedValue === null) {
      card.classList.add('invalid');
      isComplete = false;
    } else {
      clearQuestionError(card);
    }
  });
  return isComplete;
}

function calculateScore() {
  return questionCards.reduce((score, card, index) => {
    return score + (getSelectedValue(card) === correctAnswers[index] ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  scoreElement.textContent = `${score} out of 3`;
  scoreElement.dataset.score = String(score);
}

function handleOptionChange(event) {
  const card = event.target.closest('[data-testid="quiz-question"]');
  if (card) clearQuestionError(card);
  messageElement.textContent = '';
}

function handleSubmit(event) {
  event.preventDefault();
  if (!validateAnswers()) {
    messageElement.textContent = 'Please answer all three questions.';
    const firstInvalid = questionCards.find((card) => card.classList.contains('invalid'));
    if (firstInvalid) firstInvalid.querySelector('input').focus();
    return;
  }
  messageElement.textContent = '';
  displayScore(calculateScore());
}

form.addEventListener('change', handleOptionChange);
form.addEventListener('submit', handleSubmit);
